#!/usr/bin/env Rscript
# Figure contract: RNA-response ordering is definition-dependent and not exceptional
# against matched random readouts in RPE1. Evidence: all6full×5contexts -> full8null
# families -> all4parent definitions with uncertainty. Quantitative grid,183×158mm.
# R-only vector generation/native preview/actual-PDF QA; no positive-only selection.
suppressPackageStartupMessages({library(data.table);library(ggplot2);library(patchwork)})
a<-commandArgs(TRUE);project<-normalizePath(if(length(a))a[1]else'paper19opp-revision2');out<-file.path(project,'upr_robustness/specificity');fd<-file.path(out,'figure_source_data');dir.create(fd,showWarnings=FALSE)
d<-fread(file.path(out,'primary80_rank_associations.tsv'));n<-fread(file.path(out,'fixed_library_readout_specificity_calibration.tsv'))[metric=='rho']
co<-c('RPE1','Adamson','Frangieh_Control','Frangieh_IFNg','Frangieh_Coculture');cl<-c('RPE1\n438 targets','Adamson\n30 targets','Melanoma\n19 targets','IFNg\n19 targets','Co-culture\n17 targets')
full<-c('ER_folding_full','ERAD_full','ER_targeting_full','ISR_full','Reactome_UPR_full','GO_ER_UPR_full');parent<-c('Reactome_UPR_full','Reactome_UPR_no_Hallmark','GO_ER_UPR_full','GO_ER_UPR_no_Hallmark');nullorder<-c(full,'Reactome_UPR_no_Hallmark','GO_ER_UPR_no_Hallmark')
labels<-c(ER_folding_full='ER folding (9)',ERAD_full='ERAD (67)',ER_targeting_full='ER targeting (34)',ISR_full='ISR (20)',Reactome_UPR_full='Reactome UPR (69)',GO_ER_UPR_full='GO ER-UPR (41)',Reactome_UPR_no_Hallmark='Reactome disjoint (30)',GO_ER_UPR_no_Hallmark='GO disjoint (32)')
theme_set(theme_classic(base_size=7,base_family='Helvetica')+theme(axis.line=element_line(linewidth=.35),axis.ticks=element_line(linewidth=.35),axis.text=element_text(size=6),axis.title=element_text(size=7),legend.title=element_text(size=6.2),legend.text=element_text(size=6),plot.title=element_text(size=7),plot.tag=element_text(size=8,face='bold'),plot.margin=margin(5,5,5,4),panel.grid=element_blank()))
aa<-d[axis%in%full];aa[,row:=factor(axis,levels=rev(full))];aa[,column:=factor(comparison,levels=co)];aa[,label:=paste0(sprintf('%.2f',estimate),fifelse(BH80<.05,'*',''))]
tiletheme<-theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.y=element_text(size=6.1),axis.text.x=element_text(size=5.8),legend.position='bottom',legend.key.height=grid::unit(2,'mm'),legend.key.width=grid::unit(5,'mm'),plot.caption=element_text(size=5.9,hjust=0))
pA<-ggplot(aa,aes(column,row,fill=estimate))+geom_tile(colour='white',linewidth=.5)+geom_text(aes(label=label),size=1.95)+scale_x_discrete(labels=setNames(cl,co))+scale_y_discrete(labels=labels)+scale_fill_gradient2(low='#D9A16B',mid='white',high='#4C78A8',limits=c(-1,1),midpoint=0,breaks=c(-1,0,1))+labs(x=NULL,y=NULL,fill='Spearman rho',title='Six full annotated RNA readouts',caption='*BH q < 0.05 across all 80 readout/context tests.')+tiletheme
bb<-n[axis%in%nullorder];bb[,row:=factor(axis,levels=rev(nullorder))];bb[,column:=factor(comparison,levels=co)];bb[,label:=sprintf('%.2f',upper_tail_fraction)]
pB<-ggplot(bb,aes(column,row,fill=upper_tail_fraction))+geom_tile(colour='white',linewidth=.5)+geom_text(aes(label=label),size=1.95)+scale_x_discrete(labels=setNames(cl,co))+scale_y_discrete(labels=labels)+scale_fill_gradient(low='#7899BB',high='#FFFFFF',limits=c(0,1),breaks=c(0,.5,1))+labs(x=NULL,y=NULL,fill='Upper-tail fraction',title='Matched random-readout calibration',caption='100 size/expression/detection-matched nulls per readout.\nReal and null scores share fixed-library normalization.')+tiletheme
cc<-d[axis%in%parent];cc[,row:=factor(axis,levels=rev(parent))];cc[,column:=factor(comparison,levels=co)];cc[,parent:=fifelse(grepl('Reactome',axis),'Reactome','GO')];cc[,variant:=fifelse(grepl('no_Hallmark',axis),'Hallmark-disjoint','Full')]
pC<-ggplot(cc,aes(estimate,row,colour=parent,shape=variant))+geom_vline(xintercept=0,linetype=2,colour='#A0A0A0',linewidth=.3)+geom_errorbar(aes(xmin=gene_bootstrap_low,xmax=gene_bootstrap_high),orientation='y',width=.13,linewidth=.4)+geom_point(size=1.65,stroke=.45)+facet_grid(~column,labeller=labeller(column=setNames(cl,co)))+scale_y_discrete(labels=labels)+scale_x_continuous(limits=c(-1,1),breaks=c(-1,0,1))+scale_colour_manual(values=c(Reactome='#4C78A8',GO='#75658B'))+scale_shape_manual(values=c(Full=16,'Hallmark-disjoint'=1))+labs(x='Source–context Spearman correlation',y=NULL,title='Parent UPR definitions: full and Hallmark-disjoint',caption='95% whole-gene bootstrap intervals; all outcomes were previously examined.')+theme(legend.position='none',strip.background=element_blank(),strip.text=element_text(size=6.1),panel.spacing=grid::unit(2.2,'mm'),axis.text.y=element_text(size=6.2),plot.caption=element_text(size=6,hjust=0))
fig<-(pA+pB+plot_layout(widths=c(1,1.15)))/pC+plot_layout(heights=c(1.15,.85))+plot_annotation(tag_levels='a')&theme(plot.tag=element_text(size=8,face='bold'))
final<-file.path(project,'figure/Fig_UPR_readout_robustness.pdf');if(Sys.info()[['sysname']]=='Darwin')quartz(type='pdf',file=final,width=183/25.4,height=158/25.4,family='Helvetica')else cairo_pdf(final,width=183/25.4,height=158/25.4,family='Helvetica');print(fig);dev.off()
svglite::svglite(file.path(out,'Fig_UPR_readout_robustness.svg'),width=183/25.4,height=158/25.4);print(fig);dev.off();ragg::agg_png(file.path(out,'Fig_UPR_readout_robustness_preview.png'),width=183,height=158,units='mm',res=180);print(fig);dev.off()
fwrite(aa,file.path(fd,'Fig_UPR_readout_robustness_a.tsv'),sep='\t');fwrite(bb,file.path(fd,'Fig_UPR_readout_robustness_b.tsv'),sep='\t');fwrite(cc,file.path(fd,'Fig_UPR_readout_robustness_c.tsv'),sep='\t')
legend<-paste('RNA-readout transport depends on the signature and shared response variation. a, Signed K562-to-context Spearman correlations for six full curated gene-expression summaries in the fixed target panels: RPE1 (438 genes), Adamson K562 (30), untreated melanoma (19), IFNg-treated melanoma (19), and co-culture (17). Numbers in row labels are measured readout members. Asterisks indicate BH q<0.05 across all sixteen full/disjoint/unique readouts in five comparisons (80 tests); all eighty results are retained in source data. b, Observed correlation relative to one hundred random readouts matched for exact measured size and source-control expression/detection. Values are finite-control upper-tail fractions, (1+number of null correlations at least as large as the real correlation)/101, not corrected hypothesis-test P values. Both real and null scores in this panel use the same fixed 6,780-gene normalization denominator, own-member exclusion and target-specific control SD. c, Correlations for full and Hallmark-disjoint Reactome and GO UPR definitions, with 95% intervals from 4,999 whole-gene bootstrap draws. Panels a,c use exact removal of raw targeted-gene counts from the normalization denominator and remove the target from the numerator when applicable, in both treated and matched-control cells. The disjoint variants exclude the complete canonical Hallmark membership after approved-symbol mapping. Circles are filled for full and open for disjoint definitions. These analyses use already-examined outcomes and constitute specification-limited robustness, not new independent validation. Annotated RNA summaries do not measure ERAD/ISR biochemical activity or canonical UPR activation. Gene-bootstrap intervals are conditional on the measured target panels and do not supply independent culture replication. The lack of exceptional RPE1 null calibration and the failed disjoint Reactome definition limit readout-specific generalization.')
writeLines(legend,file.path(out,'Fig_UPR_readout_robustness_legend.txt'));print(pdftools::pdf_fonts(final));pdftools::pdf_convert(final,format='png',dpi=150,filenames=file.path(out,'Fig_UPR_readout_robustness_pdf_QA.png'),verbose=FALSE)
